hooks.command:
[ "$CLAUDE_CODE_REMOTE" = true ] || exit 0; case "$(cat)" in *queued-remote-notifications*|*定时巡检*) exit 0;; esac; t="${ETHAN_HOOK_TOKEN:-$ETHAN_CLOUD_TOKEN}"; [ -n "$t" ] || exit 0; r=$(curl -s -m 4 -A ethan-curfew -H "Authorization: Bearer $t" "https://ethan.example.com/cloud/curfew") || exit 0; printf '%s' "$r" | python3 -c 'import json,sys
try:
 d=json.load(sys.stdin)
except Exception:
 sys.exit(0)
if d.get("stop"):
 print(d.get("message") or "已经 11 点了，今天到这儿。", file=sys.stderr); sys.exit(2)'
